import{_ as a,c as i,o as t,aj as s}from"./chunks/framework.BlveriQe.js";const m=JSON.parse('{"title":"Admin Console","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/admin-console.md","filePath":"getting-started/admin-console.md"}'),n={name:"getting-started/admin-console.md"};function o(r,e,l,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="admin-console" tabindex="-1">Admin Console <a class="header-anchor" href="#admin-console" aria-label="Permalink to “Admin Console”">​</a></h1><p>The Primitive Admin Console is a web-based dashboard for managing your apps, users, and backend configuration. It&#39;s available at <a href="https://admin.primitiveapi.com" target="_blank" rel="noreferrer">admin.primitiveapi.com</a>.</p><h2 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What You Can Do”">​</a></h2><h3 id="app-configuration" tabindex="-1">App Configuration <a class="header-anchor" href="#app-configuration" aria-label="Permalink to “App Configuration”">​</a></h3><ul><li>View and update app settings (name, mode, allowed origins)</li><li>Manage <a href="./app-secrets.html">app secrets</a> (values write-only — never displayed after saving) and non-secret <a href="./app-secrets.html#config-vars">config vars</a> (values shown in plain text)</li><li>Configure authentication providers (Google OAuth credentials, Magic Link, OTP, Passkeys) — the Google client secret is picked from the app&#39;s <a href="./app-secrets.html">secrets</a> the same way as a webhook signing secret (below): the setting stores a <code>{{secrets.KEY}}</code> reference, never the secret itself</li><li>Manage email templates for authentication flows</li><li>Set invite-only mode for controlled access</li><li>Manage the per-app whitelist for <code>+primitivetest</code> automated-testing sign-ins (see <a href="./authentication.html#test-user-sign-in-for-automated-testing">Authentication</a>)</li></ul><h3 id="users-groups" tabindex="-1">Users &amp; Groups <a class="header-anchor" href="#users-groups" aria-label="Permalink to “Users &amp; Groups”">​</a></h3><ul><li>View all users in your app</li><li>Invite new users and manage pending invitations</li><li>Enable member invitations and set quota limits</li><li>View pending invitations and the email-based document shares or group adds attached to them</li><li>Manage console admins (who can access the admin console) and admin invitations</li><li>Manage waitlist (when in invite-only mode)</li></ul><h3 id="sharing-access" tabindex="-1">Sharing &amp; Access <a class="header-anchor" href="#sharing-access" aria-label="Permalink to “Sharing &amp; Access”">​</a></h3><ul><li>Review and approve/deny pending document access requests</li><li>Browse a user&#39;s owned and shared documents</li><li>View audit trail of share, invitation, and access-request activity</li></ul><h3 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to “Databases”">​</a></h3><ul><li>Browse databases and their types</li><li>View and test registered operations</li><li>Inspect operation <a href="./access-control.html">access rules</a> and per-subscription filter rules</li><li>Grant group-based permissions on a database</li><li>Run operations directly to verify behavior</li></ul><h3 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to “Workflows”">​</a></h3><ul><li>View workflow definitions and their status (draft, active, archived)</li><li>Manage cron triggers (create, edit, enable/disable, fire manually)</li><li>Start workflow runs with test inputs</li><li>Monitor run progress and inspect step-by-step output</li><li>View run history and debug failures</li></ul><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to “Webhooks”">​</a></h3><ul><li>Create and edit inbound webhooks — verification scheme, target workflow, timestamp tolerance, deduplication, IP allowlist</li><li>Point a signed webhook at an <a href="./app-secrets.html">app secret</a>: pick an existing key or create one without leaving the form. The webhook stores a <code>{{secrets.KEY}}</code> reference, never the secret itself, and the field appears only for the schemes that use one (<code>stripe</code>, <code>github</code>, <code>slack</code>, <code>custom</code>). Typing a key that already exists asks you to tick a confirmation before replacing its value — anything else referencing that key starts using the new value, and the old one cannot be recovered. The same confirmation appears when the app&#39;s secrets could not be listed, since the key cannot be checked</li><li>Rotate onto a different secret so both keep verifying during a provider&#39;s overlap window</li><li>Review recent deliveries with their status and rejection reason, and generate a signed test request</li><li>Free a slot under the <a href="./workflows.html#via-inbound-webhooks">50-webhook-per-app limit</a>. Archiving a webhook stops its deliveries but keeps the row, so it keeps its slot and its key; the webhooks list shows how many slots are in use and how many archived rows are still holding one. <strong>Delete permanently</strong> — on a row&#39;s menu, or from the webhook&#39;s own page — removes the row, frees the slot and releases the key for reuse. Past deliveries are kept, but the webhook&#39;s id stops resolving, so read its history first. Both actions ask you to confirm, and permanent deletion cannot be undone</li></ul><h3 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to “Prompts”">​</a></h3><ul><li>View managed prompts and their configurations</li><li>Preview rendered prompts with test inputs</li><li>Run prompt test cases</li><li>Manage prompt status (draft, active, archived)</li></ul><h3 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to “Integrations”">​</a></h3><ul><li>Configure external API connections (base URL, allowed paths, headers)</li><li>Reference credentials from <a href="./app-secrets.html">App Secrets</a> as <code>{{secrets.KEY}}</code> in <code>defaultHeaders</code> or <code>staticQuery</code></li><li>Test integrations with sample requests</li><li>View recent call logs</li></ul><h3 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to “Email Templates”">​</a></h3><ul><li>Manage the built-in email templates (the full type list is in <a href="./configuring-primitive-services.html#email-templates">Email Templates</a>)</li><li>Register custom email template types with arbitrary kebab-case names</li><li>Preview rendered templates and send test emails</li></ul><h3 id="blob-buckets" tabindex="-1">Blob Buckets <a class="header-anchor" href="#blob-buckets" aria-label="Permalink to “Blob Buckets”">​</a></h3><ul><li>Create and configure blob buckets (access policy, retention tier, access rules)</li><li>Browse blobs and generate signed URLs for inspection</li><li>Delete buckets and their contents</li></ul><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to “Analytics”">​</a></h3><ul><li>View usage metrics and event counts</li><li>Monitor daily active users</li><li>Track custom events</li><li>See <a href="./analytics.html">Analytics</a> for the emit and query APIs that feed this view</li></ul><h3 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to “Connections”">​</a></h3><ul><li>Look up the connections that are live right now for one document, user, or database</li><li>See what each connection is bound to — a document, a database subscription with its filter values, or a user&#39;s notification channel — plus when it connected and when it expires</li><li>The same view from the terminal is <code>primitive connections list</code> (see <a href="./inspecting-and-debugging.html">Inspecting and Debugging</a>)</li></ul><h2 id="when-to-use-the-console-vs-the-cli" tabindex="-1">When to Use the Console vs. the CLI <a class="header-anchor" href="#when-to-use-the-console-vs-the-cli" aria-label="Permalink to “When to Use the Console vs. the CLI”">​</a></h2><p>Both tools manage the same configuration. In practice, many developers use the console for exploring and testing, and the CLI (with <code>primitive sync</code>) for managing configuration as code — see <a href="./configuring-primitive-services.html#console-or-code">Console or Code?</a> for the full breakdown.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html">Primitive CLI</a></strong> — The command-line side of the same configuration</li><li><strong><a href="./workflows.html">Workflows</a></strong> — Define the workflows you&#39;ll test in the console</li><li><strong><a href="./api-integrations.html">API Integrations</a></strong> — Configure the integrations you&#39;ll manage in the console</li><li><strong><a href="./analytics.html">Analytics</a></strong> — Emit and query the events that show up under Analytics</li></ul>',31)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
